package v1alpha1

import (
	"testing"

	. "github.com/onsi/gomega"
	"k8s.io/apimachinery/pkg/api/resource"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

func TestAIStoreAuthTLSHelpers(t *testing.T) {
	tests := []struct {
		name              string
		authn             *AIStoreAuth
		hasTLSEnabled     bool
		useTLSSecret      bool
		useTLSCertificate bool
		useTLSCSI         bool
		tlsSecretName     string
	}{
		{
			name: "no tls",
			authn: &AIStoreAuth{
				ObjectMeta: metav1.ObjectMeta{Name: "ais-authn"},
			},
		},
		{
			name: "existing secret",
			authn: &AIStoreAuth{
				ObjectMeta: metav1.ObjectMeta{Name: "ais-authn"},
				Spec: AIStoreAuthSpec{
					TLS: &TLSSpec{
						SecretName: ptr("custom-tls"),
					},
				},
			},
			hasTLSEnabled: true,
			useTLSSecret:  true,
			tlsSecretName: "custom-tls",
		},
		{
			name: "empty secret name",
			authn: &AIStoreAuth{
				ObjectMeta: metav1.ObjectMeta{Name: "ais-authn"},
				Spec: AIStoreAuthSpec{
					TLS: &TLSSpec{
						SecretName: ptr(""),
					},
				},
			},
		},
		{
			name: "cert-manager certificate with default Secret mode",
			authn: &AIStoreAuth{
				ObjectMeta: metav1.ObjectMeta{Name: "ais-authn"},
				Spec: AIStoreAuthSpec{
					TLS: &TLSSpec{
						Certificate: &TLSCertificateConfig{
							IssuerRef: CertIssuerRef{Name: testIssuerName()},
						},
