			hostpathPrefix: aisapc.Ptr("/mnt"),
			storageClass:   aisapc.Ptr("my-sc"),
			wantClass:      aisapc.Ptr("my-sc"),
		},
		{
			name:           "stateStorage wins over deprecated options",
			stateStorage:   &StateStorage{EmptyDir: &StateEmptyDirConfig{}},
